describe('Click Target Size for Users with Motor Impairment', () => {
  beforeEach(() => {
    cy.visit('/accessibility-test');
  });

  it('should ensure click targets are at least 44x44px for users with motor impairment', () => {
    // Verify the page has a button with a class for testing
    cy.get('[data-testid="large-button"]').should('be.visible');

    // Get the computed style of the button
    cy.get('[data-testid="large-button"]').then((button) => {
      const style = window.getComputedStyle(button);
      const width = parseInt(style.width, 10);
      const height = parseInt(style.height, 10);

      // Assert the button meets the minimum size requirement
      expect(width).to.be.at.least(44);
      expect(height).to.be.at.least(44);
    });

    // Verify the button is not too small
    cy.get('[data-testid="small-button"]').should('be.visible');

    // Get the computed style of the small button
    cy.get('[data-testid="small-button"]').then((button) => {
      const style = window.getComputedStyle(button);
      const width = parseInt(style.width, 10);
      const height = parseInt(style.height, 10);

      // Assert the small button does not meet the minimum size requirement
      expect(width).to.be.lessThan(44);
      expect(height).to.be.lessThan(44);
    });
  });

  it('should handle click targets with dynamic content sizes', () => {
    // Verify a dynamic content element exists
    cy.get('[data-testid="dynamic-content-button"]').should('be.visible');

    // Intercept the API call to get dynamic content size
    cy.intercept('GET', '/api/dynamic-content-size').as('getDynamicSize');

    // Click the button to trigger the API call
    cy.get('[data-testid="dynamic-content-button"]').click();

    // Wait for the API response
    cy.wait('@getDynamicSize');

    // Verify the API returns a size that meets the requirement
    cy.get('@getDynamicSize').then((interception) => {
      const size = interception.response.body.size;
      expect(size.width).to.be.at.least(44);
      expect(size.height).to.be.at.least(44);
    });

    // Verify the button is still clickable after dynamic content load
    cy.get('[data-testid="dynamic-content-button"]').should('be.visible');
  });
});
